public final class GameObject {
    private final List<Component> components = new ArrayList<>();
    public GameObject add(Component c) { components.add(c); return this; }
    public void update(float dt) { components.forEach(c -> c.update(dt)); }

    public static GameObject createPlayer() {
        return new GameObject().add(new PlayerInputComponent())
                               .add(new ObjectPhysicComponent())
                               .add(new ObjectGraphicComponent());
    }
}

